mapper.select:

where api_method = #{apiMethod}
  and api_url = #{apiUrl}
  and api_status != -1
limit 1




        AND api_permission like concat('%', #{apiPermission}, '%')


        AND api_url like concat('%', #{apiUrl}, '%')


        AND api_method = #{apiMethod}


        AND is_need_google = #{isNeedGoogle}


        AND api_status = #{apiStatus}


        and date_format(create_time,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')


        and date_format(create_time,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')


order by create_time desc, id desc

mapper.update:
update sys_api_auth
api_permission = #{apiPermission}, api_url = #{apiUrl}, api_method = #{apiMethod}, is_need_google = #{isNeedGoogle}, api_desc = #{apiDesc}, api_status = #{apiStatus}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where id = #{id}
